/**
 * Notion Node - Version 3
 * Discriminator: resource=database, operation=get
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Get a data source */
export type NotionV3DatabaseGetParams = {
  resource: 'database';
  operation: 'get';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * The Notion database to retrieve. Use Data Source operations to search, query, or create database pages.
 * @searchListMethod getDatabases
 * @default {"mode":"list","value":""}
 */
    databaseId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @default true
 */
    simple?: boolean | Expression<boolean>;
};

export type NotionV3DatabaseGetOutput = {
  id?: string;
  name?: string;
  url?: string;
};

export type NotionV3DatabaseGetNode = {
  type: 'n8n-nodes-base.notion';
  version: 3;
  config: NodeConfig<NotionV3DatabaseGetParams> & { credentials?: Credentials };
  output?: Items<NotionV3DatabaseGetOutput>;
};